func.func @main(%arg0: tensor<6x7x3x3x3xf32>, %arg1: tensor<8x6x8x8x8xf32>) -> tensor<8x7x10x10x10xf32> {
  // Reverse spatial dims of input: dims 2,3,4 (depth, height, width)
  %rev = "stablehlo.reverse"(%arg1) {dimensions = array<i64: 2, 3, 4>} : (tensor<8x6x8x8x8xf32>) -> tensor<8x6x8x8x8xf32>

  // Perform convolution with:
  // lhs = reversed input %rev: [b=8, f=6, d=8, h=8, w=8]
  // rhs = weight %arg0: [i=6, o=7, kd=3, kh=3, kw=3]
  // dimension_numbers = [b,f,0,1,2]x[o,i,0,1,2]->[b,f,0,1,2]
  // feature_group_count = 1
  // batch_group_count = 1
  // window_strides = [1,1,1]
  // lhs_dilation = [1,1,1]
  // rhs_dilation = [1,1,1]
  // padding = [[2,2],[2,2],[2,2]] to get output spatial dims 10x10x10
  %conv = "stablehlo.convolution"(%rev, %arg0) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x8x8x8xf32>, tensor<6x7x3x3x3xf32>) -> tensor<8x7x10x10x10xf32>

  // Reverse spatial dims of output: dims 2,3,4
  %out = "stablehlo.reverse"(%conv) {dimensions = array<i64: 2, 3, 4>} : (tensor<8x7x10x10x10xf32>) -> tensor<8x7x10x10x10xf32>

  return %out : tensor<8x7x10x10x10xf32>
}

