func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %input: (6x7)
  // %weight: (7x7)
  // %bias: (7)
  // Gemm: x @ weight + bias
  %dot = "stablehlo.dot_general"(%input, %weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %x_gemm = stablehlo.add %dot, %bias : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // mean = reduce_mean(x_gemm, axis=0)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.reduce(%x_gemm, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // mean / 6 (batch_size)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_div = stablehlo.divide %mean, %six : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2, axis=0)
  // Broadcast mean_div to (6x7)
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x_gemm, %mean_bcast : tensor<6x7xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.reduce(%sq_diff, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var_div = stablehlo.divide %var, %six : tensor<7xf32>

  // Add eps to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var_div, %eps : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_bcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>

  // Scale and shift: bn_weight * x_norm + bn_bias
  %bn_weight_bcast = stablehlo.broadcast_in_dim %bn_weight {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = stablehlo.broadcast_in_dim %bn_bias {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %bn_weight_bcast, %x_norm : tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale from (1) to (6x7))
  %scale_bcast = stablehlo.broadcast_in_dim %scale {broadcast_dimensions = array<i64: 1} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_out = stablehlo.multiply %scale_bcast, %bn_out : tensor<6x7xf32>

  // Softmax along dim=1 (features dimension)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // Compute max along dim=1 (axis=1)
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %init_max = stablehlo.broadcast_in_dim %neg_inf {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6xf32>
  %max_per_row = stablehlo.reduce(%scaled_out, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %m = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %m : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<6xf32>) -> tensor<6xf32>

  // Broadcast max_per_row to (6x7)
  %max_bcast = stablehlo.broadcast_in_dim %max_per_row {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %scaled_out, %max_bcast : tensor<6x7xf32>

  // exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>

  // sum exp along dim=1
  %zero_f32_6 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %zero_f32_6 {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6xf32>
  %sum_exp = stablehlo.reduce(%exp_shifted, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %s : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<6xf32>) -> tensor<6xf32>

  // Broadcast sum_exp to (6x7)
  %sum_exp_bcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Divide exp_shifted / sum_exp_bcast
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_bcast : tensor<6x7xf32>

  stablehlo.return %softmax : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x16x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x16x8x8xf32>) -> tensor<6x1x6x6xf32> {
  // Convolution dimension numbers:
  // input:  [b, f, h, w] = [6,16,8,8]
  // kernel: [o, i, kh, kw] = [7,16,3,3]
  // output: [b, f, h_out, w_out] = [6,7,6,6]
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x6x6xf32>

  // Reduce minimum along channel dimension (dim=1), keepdim=True -> output shape [6x1x6x6]
  %init_min = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf
  %init_min_tensor = stablehlo.broadcast_in_dim %init_min {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x6x6xf32>
  %min_reduce = "stablehlo.reduce"(%conv_bias, %init_min_tensor) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min = stablehlo.minimum %a, %b : tensor<f32>
      stablehlo.return %min : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>

  // Apply tanh twice
  %tanh1 = stablehlo.tanh %min_reduce : tensor<6x1x6x6xf32>
  %tanh2 = stablehlo.tanh %tanh1 : tensor<6x1x6x6xf32>

  return %tanh2 : tensor<6x1x6x6xf32>
}

