  %zero_b = stablehlo.broadcast_in_dim(%zero) {broadcast_dimensions = array<i64: {}}> : (tensor<f32>) -> tensor<5x8xf32>

  // Select 1.0 where equal, else 0.0
  %sel = stablehlo.select(%eq, %one_b, %zero_b) : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  // Now mask out rows where idx < 0 or idx >= 8 (all zeros)
  // Compare idx >= 0
  %zero_i32 = stablehlo.constant dense<0> : tensor<i32>
  %ge0 = stablehlo.compare(%idx, %zero_i32) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
  // Compare idx < 8
  %lt8 = stablehlo.compare(%idx, %c8) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED} : (tensor<5xi32>, tensor<i32>) -> tensor<5xi1>
  // idx_in_range = ge0 AND lt8
  %idx_in_range = stablehlo.compare(%ge0, %lt8) {comparison_direction = #stablehlo<comparison_direction AND>, compare_type = #stablehlo<comparison_type NOTYPE} : (tensor<5xi1>, tensor<5xi1>) -> tensor<5xi1>

  // Broadcast idx_in_range [5] to [5x8]
  %idx_in_range_b = stablehlo.broadcast_in_dim(%idx_in_range) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi1>) -> tensor<5x8xi1>

  // Select final output: if idx_in_range_b then sel else zero
  %out = stablehlo.select(%idx_in_range_b, %sel, %zero_b) : (tensor<5x8xi1>, tensor<5x8xf32>, tensor<5x8xf32>) -> tensor<5x8xf32>

  return %out : tensor<5x8xf32>
}

