  %cmp = stablehlo.compare %x, %c0 {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<3x7xf32>, tensor<f32>) -> tensor<3x7xi1>
  %cfalse = stablehlo.constant dense<false> : tensor<i1>
  %init = stablehlo.convert %cfalse : (tensor<i1>) -> tensor<i32>
  %count = stablehlo.reduce(%cmp, %init) ({
