func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x7xf32>) -> tensor<8x6x9x9xf32> {
  // %arg0: weight tensor of shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor of shape [batch=8, channels=6, height=7, width=7]

  // Step 1: Reverse the spatial dimensions of the weight tensor to simulate kernel flip for transposed conv.
  // The weight shape is [6, 6, 3, 3], dims: 0=in_channels,1=out_channels,2=H,3=W
  // Reverse dims 2 and 3 (kernel height and width)
  %reversed_weight = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Perform convolution with swapped lhs/rhs roles and adjusted dimension_numbers for transposed conv.
  // Transposed conv can be implemented as a convolution with:
  // - lhs = input tensor (batch, in_channels, H, W)
  // - rhs = reversed weight tensor (in_channels, out_channels, KH, KW)
  // But stablehlo.convolution expects rhs shape: [output_channels, input_channels/groups, KH, KW]
  // Our reversed_weight is [in_channels, out_channels, KH, KW], so we need to swap dims 0 and 1.

  // Swap dims 0 and 1 of reversed_weight to get shape [out_channels, in_channels, KH, KW]
  // Use transpose operation to permute dims [1, 0, 2, 3]
  %weight_transposed = "stablehlo.transpose"(%reversed_weight) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 3: Define convolution parameters for transposed conv:
  // Given:
  // input shape: [8, 6, 7, 7]
  // weight shape after transpose: [6, 6, 3, 3]
  // stride = 1 (default)
  // padding = 0 (default)
  // output_padding = 0 (default)
  // groups = 1 (default)

  // For transposed conv, the convolution parameters are:
  // window_strides = [1,1]
  // padding = [[kernel_h - 1, kernel_h - 1], [kernel_w - 1, kernel_w - 1]] = [[2,2],[2,2]]
  // lhs_dilation = [1,1]
  // rhs_dilation = [1,1]
  // dimension_numbers = [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
  // But for transposed conv, the input channels correspond to rhs input channels, so dimension_numbers must be:
  // lhs: [b, f, h, w] = input
  // rhs: [o, i, kh, kw] = weight
  // output: [b, f, h_out, w_out]

  // Here, f dimension in lhs is input channels (6)
  // rhs dimension i is input channels (6), o is output channels (6)
  // feature_group_count = 1

  // Compute padding as kernel_size - 1 = 3 - 1 = 2 on both sides
  %padding = dense<[[2, 2], [2, 2]]> : tensor<2x2xi64>

  %result = "stablehlo.convolution"(%arg1, %weight_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = %padding,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x9xf32>

  return %result : tensor<8x6x9x9xf32>
}

