func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: y = x @ W^T + b
  // %arg0 is weight: tensor<7x7xf32> (out_features x in_features)
  // %arg2 is input: tensor<6x7xf32> (batch_size x in_features)
  // We want to do dot_general with contracting dims: input's last dim (1), weight's last dim (1)
  // But weight needs to be transposed to shape (7x7) -> (7x7), but we want to contract input dim 1 with weight dim 1,
  // so we transpose weight to swap dims 0 and 1 to get (7x7) -> (7x7) (actually same shape, but transpose swaps dims)
  // Actually, weight shape is (7x7), input shape is (6x7)
  // To do x @ W^T, we transpose weight to (7x7) with permutation [1,0]
  // Then dot_general with contracting dims input dim 1 and weight dim 0 (since weight is transposed)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %linear = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias from shape [7] to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_bias = "stablehlo.add"(%linear, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Define Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  // stablehlo has log_plus_one and exponential ops
  %exp_linear_bias = "stablehlo.exponential"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %softplus = "stablehlo.log_plus_one"(%exp_linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %tanh_softplus = "stablehlo.tanh"(%softplus) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %mish1 = "stablehlo.multiply"(%linear_bias, %tanh_softplus) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Apply Mish again
  %exp_mish1 = "stablehlo.exponential"(%mish1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %softplus2 = "stablehlo.log_plus_one"(%exp_mish1) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %tanh_softplus2 = "stablehlo.tanh"(%softplus2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %mish2 = "stablehlo.multiply"(%mish1, %tanh_softplus2) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %mish2 : tensor<6x7xf32>
}

