func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bmm.weight (7x7)
  // %arg1 = bmm.bias (7)
  // %arg2 = input x (6x7)
  // %arg3 = input y (6x7)

  // Compute x = bmm(x) = x @ weight^T + bias
  // stablehlo.dot_general with contracting dims: x dims 1 and weight dims 1 (weight is 7x7, we want weight^T)
  // So we transpose weight to get 7x7 -> 7x7 (transpose dims [1,0])
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %bmm_dot = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [0], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bmm_out = "stablehlo.add"(%bmm_dot, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // InstanceNorm2d on x.unsqueeze(1).unsqueeze(1)
  // x shape: (6,7)
  // unsqueeze dims 1 and 2 -> shape (6,1,1,7)
  // We reshape to (6,1,1,7)
  %x_reshaped = "stablehlo.reshape"(%bmm_out) : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>

  // Compute mean over spatial dims (1,2) for each batch and channel
  // mean = reduce sum over dims 1 and 2, then divide by 1*1=1 (so sum is mean)
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %mean_sum = "stablehlo.reduce"(%x_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> = {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1, 2>} : (tensor<6x1x1x7xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute variance: mean of squared differences
  // First compute (x - mean)^2
  // Broadcast mean (6x7) to (6x1x1x7)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_sum) {broadcast_dimensions = array<i64: 0, 3>} : (tensor<6x7xf32>) -> tensor<6x1x1x7xf32>
  %diff = "stablehlo.subtract"(%x_reshaped, %mean_bcast) : (tensor<6x1x1x7xf32>, tensor<6x1x1x7xf32>) -> tensor<6x1x1x7xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x1x1x7xf32>, tensor<6x1x1x7xf32>) -> tensor<6x1x1x7xf32>

  // variance = mean of diff_sq over dims 1 and 2 (same as sum since dims are 1)
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> = {
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }
