func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Perform linear: x @ W^T + b
  // %arg0 is linear.weight: tensor<7x7xf32> (out_features x in_features)
  // %arg1 is linear.bias: tensor<7xf32>
  // %arg2 is input: tensor<6x7xf32> (batch_size x in_features)

  // Transpose weight to shape (7,7) -> (7,7) but swap dims to get W^T: (7,7)
  // Actually weight shape is (out_features, in_features) = (7,7)
  // Input shape is (batch_size, in_features) = (6,7)
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1 (in_features)
  // So dot_general lhs: (6,7), rhs: (7,7)
  // Contract lhs dim 1 with rhs dim 1 (both in_features)
  // Result shape: (6,7) (batch_size x out_features)

  %0 = "stablehlo.dot_general"(%arg2, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias from (7) to (6x7)
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>

  %2 = stablehlo.add %0, %1 : tensor<6x7xf32>

  // Apply ReLU: max(x, 0)
  %cst_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %3 = "stablehlo.broadcast_in_dim"(%cst_zero) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %4 = stablehlo.maximum %2, %3 : tensor<6x7xf32>

  // Divide by divisor = 2.0 (constant)
  %cst_two = stablehlo.constant dense<2.0> : tensor<f32>
  %5 = "stablehlo.broadcast_in_dim"(%cst_two) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %6 = stablehlo.divide %4, %5 : tensor<6x7xf32>

  return %6 : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = gemm.weight: tensor<7x7xf32>
  // %arg1 = gemm.bias: tensor<7xf32>
  // %arg2 = input: tensor<6x7xf32>

  // Perform gemm: x @ W^T + b
  // Transpose weight from (7x7) to (7x7) swapping dims 0 and 1 (W^T)
  %weight_t = stablehlo.transpose %arg0 {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot general: batch dims empty, contracting dims: input dim 1 and weight_t dim 0
  %dot = stablehlo.dot_general %arg2, %weight_t 
    {dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [], rhs_batching_dimensions = [], 
      lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} 
    : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x : tensor<6x7xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  // Broadcast one to tensor<6x7xf32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_exp = stablehlo.add %one_broadcast, %exp_neg_x : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %one_plus_exp : tensor<6x7xf32>
  %swish = stablehlo.multiply %x, %sigmoid : tensor<6x7xf32>

  // Divide by 2.0
  %two = stablehlo.constant dense<2.0> : tensor<f32>
  %two_broadcast = stablehlo.broadcast_in_dim %two {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %div = stablehlo.divide %swish, %two_broadcast : tensor<6x7xf32>

  // Clamp between -1.0 and 1.0
  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = stablehlo.broadcast_in_dim %neg_one {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %one_broadcast2 = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  %clamp_min = stablehlo.maximum %div, %neg_one_broadcast : tensor<6x7xf32>
  %clamp = stablehlo.minimum %clamp_min, %one_broadcast2 : tensor<6x7xf32>

  // Tanh activation
  %tanh = stablehlo.tanh %clamp : tensor<6x7xf32>

  // Clamp again between -1.0 and 1.0
  %clamp_min2 = stablehlo.maximum %tanh, %neg_one_broadcast : tensor<6x7xf32>
  %clamp2 = stablehlo.minimum %clamp_min2, %one_broadcast2 : tensor<6x7xf32>

  return %clamp2 : tensor<6x7xf32>
}

