func.func @main(%x: tensor<3x5xf32>, %y: tensor<6x5xf32>) -> tensor<3x6xf32> {
  // Broadcast x from [3,5] to [3,6,5] by adding a new dim at position 1
  %x_broadcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0, 2>} : (tensor<3x5xf32>) -> tensor<3x6x5xf32>
  // Broadcast y from [6,5] to [3,6,5] by adding a new dim at position 0
  %y_broadcast = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 1, 2>} : (tensor<6x5xf32>) -> tensor<3x6x5xf32>
  // Compute difference (x[i,d] - y[j,d]) broadcasted to [3,6,5]
  %diff = "stablehlo.subtract"(%x_broadcast, %y_broadcast) : (tensor<3x6x5xf32>, tensor<3x6x5xf32>) -> tensor<3x6x5xf32>
  // Square the difference element-wise
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<3x6x5xf32>, tensor<3x6x5xf32>) -> tensor<3x6x5xf32>
  // Create zero constant for reduction init
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Reduce sum over dimension 2 (the 5 dimension)
  %out = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<3x6x5xf32>, tensor<f32>) -> tensor<3x6xf32>
  return %out : tensor<3x6xf32>
}

func.func @main(%bias: tensor<6x1x1xf32>, %conv_transpose_weight: tensor<7x6x4x4xf32>, %conv_transpose_bias: tensor<6xf32>, %input: tensor<6x7x7x7xf32>) -> tensor<6x6x15x15xf32> {
  // Step 1: Perform ConvTranspose2d as a convolution with appropriate parameters.
  // ConvTranspose2d parameters:
  // in_channels=7, out_channels=6, kernel_size=4, stride=2, padding=1, output_padding=1
  // Input shape: [batch=6, in_channels=7, H=7, W=7]
  // Weight shape: [in_channels=7, out_channels=6, KH=4, KW=4] in PyTorch conv_transpose.weight
  // StableHLO convolution expects rhs shape: [o, i, KH, KW]
  // Given conv_transpose_weight shape: [7,6,4,4], we must transpose to [6,7,4,4]
  // We'll reshape and transpose conv_transpose_weight to [6,7,4,4]

  // Reshape conv_transpose_weight from [7x6x4x4] to [7,6,16]
  %w_reshape = stablehlo.reshape %conv_transpose_weight : (tensor<7x6x4x4xf32>) -> tensor<7x6x16xf32>
  // Transpose dims [1,0,2] to get [6,7,16]
  %w_transpose = "stablehlo.transpose"(%w_reshape) {permutation = array<i64: 1, 0, 2>} : (tensor<7x6x16xf32>) -> tensor<6x7x16xf32>
  // Reshape back to [6x7x4x4]
  %w = stablehlo.reshape %w_transpose : (tensor<6x7x16xf32>) -> tensor<6x7x4x4xf32>

  // ConvTranspose2d as convolution with:
  // window_strides = output stride = 1 (since conv_transpose stride=2, convolution stride=1)
  // lhs_dilation = stride of conv_transpose = 2
  // rhs_dilation = 1
  // padding = padding for conv_transpose = 1
  // output_padding = 1 (handled by padding adjustment)
  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw], output [b, f, h, w]
  // feature_group_count = 1
  // batch_group_count = 1

  // Calculate padding for convolution:
  // For conv_transpose, padding = kernel_size - 1 - padding = 4 - 1 - 1 = 2
  // But output_padding=1 means we add 1 more padding at the end
  // So total padding low = kernel_size - 1 - padding = 2
  // total padding high = padding low + output_padding = 2 + 1 = 3
  // So padding = [[2,3], [2,3]]

  %conv = "stablehlo.convolution"(%input, %w) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[2, 3], [2, 3]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 2, 3]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x15x15xf32>

  // Step 2: Apply softmax along dim=1 (channels)
  // Softmax(x) = exp(x) / sum(exp(x), dim=1)
  // Compute exp(x)
  %exp_conv = stablehlo.exponential %conv : tensor<6x6x15x15xf32>

  // Compute sum over dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = array<i64: 0, 2, 3>} : (tensor<f32>) -> tensor<6x1x15x15xf32>

  %sum_exp = "stablehlo.reduce"(%exp_conv, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x6x15x15xf32>, tensor<6x1x15x15xf32>) -> tensor<6x1x15x15xf32>

  // Broadcast sum_exp to shape of exp_conv for division
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x15x15xf32>) -> tensor<6x6x15x15xf32>

  // Divide exp_conv by sum_exp_broadcast to get softmax
  %softmax = stablehlo.divide %exp_conv, %sum_exp_broadcast : tensor<6x6x15x15xf32>

  // Step 3: Add bias (shape [6x1x1]) broadcasted to [6x6x15x15]
  %bias_broadcast = stablehlo.broadcast_in_dim %bias {broadcast_dimensions = array<i64: 1} : (tensor<6x1x1xf32>) -> tensor<6x6x15x15xf32>
  %add_bias = stablehlo.add %softmax, %bias_broadcast : tensor<6x6x15x15xf32>

  // Step 4: Multiply by scaling factor 2.0
  %scale_val = stablehlo.constant dense<2.0> : tensor<f32>
  %scale = stablehlo.broadcast_in_dim %scale_val {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
  %scaled = stablehlo.multiply %add_bias, %scale : tensor<6x6x15x15xf32>

  // Step 5: Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_scaled = stablehlo.negate %scaled : tensor<6x6x15x15xf32>
  %exp_neg = stablehlo.exponential %neg_scaled : tensor<6x6x15x15xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x15x15xf32>
  %denominator = stablehlo.add %one_broadcast, %exp_neg : tensor<6x6x15x15xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denominator : tensor<6x6x15x15xf32>

  // Return final result
  return %sigmoid : tensor<6x6x15x15xf32>
}

