func.func @main(%multiply_weight: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %group_norm_weight: tensor<16xf32>, %group_norm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // GEMM: x = input @ gemm_weight^T + gemm_bias
  // gemm_weight shape: [16,16], we want to contract input's last dim with gemm_weight's last dim
  // So transpose gemm_weight to [16x16] with permutation [1,0]
  %gemm_weight_t = stablehlo.transpose %gemm_weight {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm = stablehlo.dot_general %input, %gemm_weight_t 
    {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} 
    : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x_gemm_bias = stablehlo.broadcast_in_dim %gemm_bias {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x = stablehlo.add %x_gemm, %x_gemm_bias : tensor<16x16xf32>

  // GroupNorm:
  // Parameters:
  // num_groups = 16, out_features = 16, so group size = 1 (16/16)
  // Reshape x to [batch, num_groups, group_size] = [16,16,1]
  %x_reshape = stablehlo.reshape %x : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over group_size dimension (dim=2)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %x_reshape, %init_zero 
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 2}} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Compute variance: mean of (x - mean)^2 over group_size dimension (dim=2)
  // Broadcast mean to [16x16x1]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %x_reshape, %mean_broadcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %init_zero_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = stablehlo.reduce %diff_sq, %init_zero_var 
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 2}} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %eps : tensor<16x16xf32>
  %var_eps_sqrt = stablehlo.sqrt %var_eps : tensor<16x16xf32>
  %var_eps_sqrt_broadcast = stablehlo.broadcast_in_dim %var_eps_sqrt {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %x_norm = stablehlo.divide %diff, %var_eps_sqrt_broadcast : tensor<16x16x1xf32>

  // Reshape normalized x back to [16x16]
  %x_norm_reshape = stablehlo.reshape %x_norm : tensor<16x16x1xf32> -> tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias (both shape [16])
  // Broadcast group_norm.weight and bias to [16x16]
  %gn_weight_broadcast = stablehlo.broadcast_in_dim %group_norm_weight {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_broadcast = stablehlo.broadcast_in_dim %group_norm_bias {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_scaled = stablehlo.multiply %x_norm_reshape, %gn_weight_broadcast : tensor<16x16xf32>
  %x_shifted = stablehlo.add %x_scaled, %gn_bias_broadcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x_shifted : tensor<16x16xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<16x16xf32>
  %denom = stablehlo.add %one_broadcast, %exp_neg_x : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %denom : tensor<16x16xf32>
  %x_swish = stablehlo.multiply %x_shifted, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]), broadcast to [16x16]
  %multiply_weight_broadcast = stablehlo.broadcast_in_dim %multiply_weight {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_mul = stablehlo.multiply %x_swish, %multiply_weight_broadcast : tensor<16x16xf32>

  // Swish again: x_mul * sigmoid(x_mul)
  %neg_x_mul = stablehlo.negate %x_mul : tensor<16x16xf32>
  %exp_neg_x_mul = stablehlo.exponential %neg_x_mul : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_broadcast, %exp_neg_x_mul : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_broadcast, %denom2 : tensor<16x16xf32>
  %output = stablehlo.multiply %x_mul, %sigmoid2 : tensor<16x16xf32>

  return %output : tensor<16x16xf32>
}

func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %input: [6,7], %weight: [7,7], compute gemm: x @ W^T + bias
  // gemm.weight is [7,7], PyTorch Linear does input @ weight.T + bias
  // So transpose weight to [7,7] (actually same shape), but we must do dot_general with contracting dims:
  // input: [6,7], weight: [7,7], contract input dim 1 with weight dim 1 (weight.T dim 0)
  // So we transpose weight to get weight.T: [7,7] -> [7,7] (transpose dims 0,1)
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]
  %gemm = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // add bias: bias shape [7], broadcast to [6,7]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %gemm_bias = "stablehlo.add"(%gemm, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // multiply by scale: scale shape [7], broadcast to [6,7]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = "stablehlo.multiply"(%gemm_bias, %scale_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // batch norm forward (training mode):
  // compute mean over batch dim 0: reduce over dim 0 with add, then divide by 6
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum = "stablehlo.reduce"(%scaled, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = "stablehlo.divide"(%sum, %six_bcast) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // compute variance: mean((x - mean)^2) over batch dim 0
  // broadcast mean to [6,7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = "stablehlo.subtract"(%scaled, %mean_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %zero_var = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum_var = "stablehlo.reduce"(%sq, %zero_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
