      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = "stablehlo.divide"(%sum_var, %six_bcast) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // add eps=1e-5 to variance
  %eps = "stablehlo.constant"() {value = dense<1.00000001e-5> : tensor<f32>} : () -> tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = "stablehlo.add"(%var, %eps_bcast) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // compute rsqrt(var + eps)
  %inv_std = "stablehlo.rsqrt"(%var_eps) : (tensor<7xf32>) -> tensor<7xf32>
