  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %norm = "stablehlo.multiply"(%diff, %inv_std_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // scale and shift: norm * bn_weight + bn_bias
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled_norm = "stablehlo.multiply"(%norm, %bn_weight_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %out = "stablehlo.add"(%scaled_norm, %bn_bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  return %out : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x @ W^T + b
  // %arg0 = linear.weight (7x7), %arg1 = linear.bias (7), %arg2 = input (6x7)
  // We need to do dot_general with contracting dims: input last dim (7), weight last dim (7)
  // But weight shape is (7x7), linear expects weight shape (out_features x in_features)
  // PyTorch Linear weight shape is (out_features, in_features) = (7,7)
  // Input shape is (batch_size, in_features) = (6,7)
  // So output shape is (batch_size, out_features) = (6,7)
  // dot_general lhs: %arg2 (6x7), rhs: %arg0 (7x7)
  // Contract lhs dim 1 with rhs dim 1, but rhs dim 1 is in_features, so we must transpose rhs to (7x7) -> (7x7) no change?
  // Actually, PyTorch linear does x @ W^T, so we must transpose weight to (7x7) -> (7x7) (same shape)
  // But to do x @ W^T, we do dot_general with contracting dims lhs:1, rhs:0 (rhs transposed)
  // So transpose weight from (7x7) to (7x7) with permutation [1,0]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %linear = "stablehlo.dot_general"(%arg2, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_bias = "stablehlo.add"(%linear, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = "stablehlo.negate"(%linear_bias) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %exp = "stablehlo.exponential"(%neg) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %denominator = "stablehlo.add"(%one_broadcast, %exp) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %sigmoid = "stablehlo.divide"(%one_broadcast, %denominator) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Sum over dim=1 (features), keepdim=True -> output shape (6x1)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x1xf32>
  %sum = "stablehlo.reduce"(%sigmoid, %zero_broadcast) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  return %sum : tensor<6x1xf32>
}

func.func @main(%arg0: tensor<12x32xf32>, %arg1: tensor<32x12xf32>) -> tensor<12x12xf32> {
  %0 = "stablehlo.dot_general"(%arg0, %arg1) {
