  %c3_bcast = "stablehlo.broadcast_in_dim"(%c3) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<1xf32> } : (tensor<f32>) -> tensor<1xf32>
  %c3_bcast_4d = "stablehlo.broadcast_in_dim"(%c3) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<1xf32> } : (tensor<f32>) -> tensor<1xf32>
