  %c3_4d = stablehlo.constant dense<3.0> : tensor<f32>
  %c3_bcast_6x7x4x4 = "stablehlo.broadcast_in_dim"(%c3_4d) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %3 = stablehlo.add %2, %c3_bcast_6x7x4x4 : tensor<6x7x4x4xf32>

  // Compute relu6(x + 3) = min(max(x + 3, 0), 6)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %c6_bcast = "stablehlo.broadcast_in_dim"(%c6) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %4 = stablehlo.maximum %3, %c0_bcast : tensor<6x7x4x4xf32>
  %5 = stablehlo.minimum %4, %c6_bcast : tensor<6x7x4x4xf32>

