  %7 = stablehlo.divide %6, %c6_bcast : tensor<6x7x4x4xf32>

  // ReLU: max(0, x)
  %8 = stablehlo.maximum %7, %c0_bcast : tensor<6x7x4x4xf32>

  return %8 : tensor<6x7x4x4xf32>
}

