func.func @main(%weight: tensor<6xf32>, %bias: tensor<6xf32>, %x: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  // Compute mean over axes [0, 2, 3] for each feature channel (axis 1)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce(%x, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute variance over axes [0, 2, 3]
  // First compute (x - mean_broadcast)^2
  // Broadcast mean to shape of x: broadcast mean from [6] to [6x6x7x7] with broadcast_dimensions=[1]
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %diff = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6x7x7xf32>

  %c0_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = stablehlo.reduce(%diff_sq, %c0_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Compute divisor = N = batch_size * dim1 * dim2 = 6*7*7=294
  %c294 = stablehlo.constant dense<294.0> : tensor<f32>

  // variance = var / 294
  %var_mean = stablehlo.divide %var, %c294 : tensor<6xf32>

  // epsilon = 1e-5 for numerical stability
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var_mean, %c_eps : tensor<6xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6xf32>

  // Normalize: (x - mean) * inv_std
  %diff_norm = stablehlo.subtract %x, %mean_broadcast : tensor<6x6x7x7xf32>
  // Broadcast inv_std from [6] to [6x6x7x7] with broadcast_dimensions=[1]
  %inv_std_broadcast = stablehlo.broadcast_in_dim %inv_std {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %x_norm = stablehlo.multiply %diff_norm, %inv_std_broadcast : tensor<6x6x7x7xf32>

  // Broadcast weight and bias from [6] to [6x6x7x7] with broadcast_dimensions=[1]
  %weight_broadcast = stablehlo.broadcast_in_dim %weight {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>
  %bias_broadcast = stablehlo.broadcast_in_dim %bias {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x7x7xf32>

  // Apply scale and shift: y = weight * x_norm + bias
  %scaled = stablehlo.multiply %x_norm, %weight_broadcast : tensor<6x6x7x7xf32>
  %y = stablehlo.add %scaled, %bias_broadcast : tensor<6x6x7x7xf32>

  return %y : tensor<6x6x7x7xf32>
}

func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0 = bias (tensor<16xf32>)
  // %arg1 = matmul.weight (tensor<16x16xf32>)
  // %arg2 = matmul.bias (tensor<16xf32>)
  // %arg3 = group_norm.weight (tensor<16xf32>)
  // %arg4 = group_norm.bias (tensor<16xf32>)
  // %arg5 = input x (tensor<16x16xf32>)

  // Step 1: matmul: x @ weight^T + bias
  // matmul.weight shape: [16,16], input shape: [16,16]
  // PyTorch Linear does x @ weight.T + bias, so we transpose weight
  %weight_t = stablehlo.transpose %arg1 {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %matmul = stablehlo.dot_general %arg5, %weight_t 
    {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} 
    : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add matmul.bias (arg2) broadcasted over batch dimension
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // Step 2: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_matmul_bias = stablehlo.negate %matmul_bias : tensor<16x16xf32>
  %exp_neg = stablehlo.exponential %neg_matmul_bias : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %one_plus_exp = stablehlo.add %one_broadcast, %exp_neg : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %one_plus_exp : tensor<16x16xf32>
  %swish = stablehlo.multiply %matmul_bias, %sigmoid : tensor<16x16xf32>

  // Step 3: Add bias (arg0) broadcasted over batch dimension
  %bias0_broadcast = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias0_broadcast : tensor<16x16xf32>

  // Step 4: GroupNorm
  // GroupNorm with num_groups=16, out_features=16 means each channel is its own group
  // Input shape: [batch=16, channels=16]
  // Compute mean and variance over group dimension (which is channel dimension here)
  // So for each batch element, mean and variance over channels dimension (dim=1)

  // Compute mean over channels (dim=1)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>
  %mean = stablehlo.reduce %swish_bias, %zero_f32 
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

