  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %epsilon_broadcast = stablehlo.broadcast_in_dim %epsilon {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>
  %var_eps = stablehlo.add %var_mean, %epsilon_broadcast : tensor<16xf32>

