      stablehlo.return %m : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 2, 2>,
    window_strides = array<i64: 1, 1, 2, 2>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Divide by 4 (kernel_size_pool^2) to get average
  %c_4 = stablehlo.constant dense<4.0> : tensor<f32>
  %c_4_bcast = "stablehlo.broadcast_in_dim"(%c_4) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<f32>) -> tensor<6x6x2x2xf32>
  %avgpool = stablehlo.divide %sum, %c_4_bcast : tensor<6x6x2x2xf32>

