  %conv_out_bias = "stablehlo.add"(%conv_out, %conv_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Compute batch mean over axes [0,2,3] (batch, height, width)
