      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute batch variance over axes [0,2,3]
  // variance = mean((x - mean)^2)
  // Broadcast mean to conv_out_bias shape for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %diff = "stablehlo.subtract"(%conv_out_bias, %mean_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

