  %sqrt_var_eps = "stablehlo.sqrt"(%var_eps) : (tensor<7xf32>) -> tensor<7xf32>
  %inv_sqrt_var_eps = "stablehlo.divide"(%zero_f32_2, %sqrt_var_eps) : (tensor<f32>, tensor<7xf32>) -> tensor<7xf32>
