  // We want 1 / sqrt(var + eps), so create constant 1.0 and divide by sqrt_var_eps.

  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %inv_sqrt_var_eps = "stablehlo.divide"(%one, %sqrt_var_eps) : (tensor<f32>, tensor<7xf32>) -> tensor<7xf32>

  // Compute normalized output: (x - mean) * inv_sqrt_var_eps
  // Broadcast inv_sqrt_var_eps to conv_out_bias shape
