  %x_centered = "stablehlo.subtract"(%conv_out_bias, %mean_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
  %x_norm = "stablehlo.multiply"(%x_centered, %inv_sqrt_var_eps_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Apply bn.weight (gamma) and bn.bias (beta)
  // bn.weight and bn.bias shape: [7], broadcast to [6,7,4,4]
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %scaled = "stablehlo.multiply"(%x_norm, %bn_weight_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>
  %shifted = "stablehlo.add"(%scaled, %bn_bias_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

