  %scaling_factor = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %scaling_factor_bcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
