  %output = "stablehlo.multiply"(%shifted, %scaling_factor_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  return %output : tensor<6x7x4x4xf32>
}

