  %c_zero_bcast = stablehlo.broadcast_in_dim %c_zero {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>
  %sum_exp = stablehlo.reduce(%exp, %c_zero_bcast) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
