  %sum_exp_bcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Divide exp by sum_exp to get softmax output
  %softmax = stablehlo.divide %exp, %sum_exp_bcast : tensor<6x7xf32>

  return %softmax : tensor<6x7xf32>
}

