  // dimension_numbers: input [b, f, h, w], kernel [o, i, kh, kw] -> output [b, f, oh, ow]
  // Here, input channels = 6, output channels = 7, batch = 6
  // The convolution will produce output shape:
  // out_h = (7 - 1)*1 - 0 + (3 - 1)*1 + 1 = 7 - 0 + 2 + 1 = 10 (but we want 9)
  // out_w = (8 - 1)*1 - 0 + (5 - 1)*1 + 1 = 8 - 0 + 4 + 1 = 13 (but we want 12)
  // So we need to adjust padding to get output 9x12.
  // Using formula for transposed conv output size:
  // output = (input - 1)*stride - 2*padding + dilation*(kernel_size -1) + output_padding + 1
  // Given stride=1, padding=0, dilation=1, output_padding=0:
  // output_h = (7-1)*1 - 0 + 1*(3-1) + 0 + 1 = 6 + 2 + 1 = 9
  // output_w = (8-1)*1 - 0 + 1*(5-1) + 0 + 1 = 7 + 4 + 1 = 12
  // So padding=0 is correct.

  %conv = "stablehlo.convolution"(%arg1, %reversed_kernel) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 2, 3]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x8xf32>, tensor<6x7x3x5xf32>) -> tensor<6x7x9x12xf32>

  return %conv : tensor<6x7x9x12xf32>
}

