  // Broadcast targets %arg1 from shape [6] to [6x6] to match predictions shape.
  %bcast_targets = stablehlo.broadcast_in_dim %arg1 
    {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x6xf32>

  // Compute element-wise product: predictions * targets
