  %one_bcast = stablehlo.broadcast_in_dim %one 
    {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %diff = stablehlo.subtract %one_bcast, %prod : tensor<6x6xf32>

  // Clamp with min=0: max(0, 1 - predictions * targets)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = stablehlo.broadcast_in_dim %zero 
    {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %clamped = stablehlo.maximum %diff, %zero_bcast : tensor<6x6xf32>

  // Reduce mean over all elements: sum then divide by 36 (6*6)
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = stablehlo.reduce(%clamped, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // Divide sum by 36.0 to get mean
  %divisor = stablehlo.constant dense<36.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %divisor : tensor<f32>

  return %mean : tensor<f32>
}

