  // Step 4: Divide by divide_value = 1.0 (no-op)
  // We skip division since divide_value=1.0

  // Step 5: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_biased = "stablehlo.negate"(%biased) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %exp_neg = "stablehlo.exponential"(%neg_biased) : (tensor<6x7xf32>) -> tensor

