func.func @main(%arg0: tensor<6x7x8xf32>) -> tensor<6x7x9xf32> {
  // Constants for AvgPool1d parameters
  %c_kernel_size = stablehlo.constant dense<8> : tensor<i64>
  %c_stride = stablehlo.constant dense<1> : tensor<i64>
  %c_padding = stablehlo.constant dense<4> : tensor<i64>

