  // %arg1 = gemm.bias (7)
  // %arg2 = input (6x7)

  // Perform gemm: x @ weight^T + bias
  // weight^T: transpose %arg0 from 7x7 to 7x7 (actually same shape, but transpose dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

