  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add = "stablehlo.add"(%dot, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Multiply by multiplier = 2.0 (constant)
  %c_two = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  // Broadcast scalar multiplier to (6x7)
  %multiplier = "stablehlo.broadcast_in_dim"(%c_two) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>
  // Note: stablehlo.broadcast_in_dim requires broadcast_dimensions length = rank(operand)
  // For scalar operand rank=0, broadcast_dimensions = [] (empty array)
  %multiplier = "stablehlo.broadcast_in_dim"(%c_two) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>

  %mul = "stablehlo.multiply"(%add, %multiplier) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // LeakyReLU with negative_slope = 0.1
  // LeakyReLU(x) = max(0, x) + negative_slope * min(0, x)
  // Compute zero tensor of shape (6x7)
  %c_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero = "stablehlo.broadcast_in_dim"(%c_zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>

  // Compare x > 0
  %cmp = "stablehlo.compare"(%mul, %zero) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xi1>

  // Select max(0, x)
  %max_part = "stablehlo.select"(%cmp, %mul, %zero) : (tensor<6x7xi1>, tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Select min(0, x) = select(x > 0, 0, x)
  %min_part = "stablehlo.select"(%cmp, %zero, %mul) : (tensor<6x7xi1>, tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // negative_slope constant 0.1
  %c_neg_slope = "stablehlo.constant"() {value = dense<0.1> : tensor<f32>} : () -> tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%c_neg_slope) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7xf32>

  // Multiply negative_slope * min_part
  %neg_slope_mul = "stablehlo.multiply"(%neg_slope_broadcast, %min_part) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Add max_part + negative_slope * min_part
  %leaky_relu = "stablehlo.add"(%max_part, %neg_slope_mul) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %leaky_relu : tensor<6x7xf32>
}

