  %scale_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %scale_bcast2 = "stablehlo.broadcast_in_dim"(%scale_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>

