  // window_dimensions = [1, 1, 8]
  // window_strides = [1, 1, 1]
  // base_dilations = [1, 1, 3]
  // padding = [[0,0], [0,0], [4,4]]

  %c_init = stablehlo.constant dense<-inf> : tensor<f32>

  %result = "stablehlo.reduce_window"(%arg0, %c_init)
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %max = stablehlo.maximum %a, %b : tensor<f32>
        stablehlo.return %max : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 8>,
      window_strides = array<i64: 1, 1, 1>,
      base_dilations = array<i64: 1, 1, 3>,
      padding = dense<[[0, 0], [0, 0], [4, 4]]> : tensor<3x2xi64>
    } : (tensor<16x12x16xf32>, tensor<f32>) -> tensor<16x12x3xf32>

  return %result : tensor<16x12x3xf32>
}

func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Save original input for residual add
  %original_x = %input : tensor<6x7xf32>

  // GEMM: x = input @ weight^T + bias
  // weight shape: [7,7], input shape: [6,7]
  // We want to do input [6x7] dot weight^T [7x7] -> [6x7]
  // So contract dimension is input dim 1 and weight dim 1
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %x_gemm = "stablehlo.dot_general"(%input, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %x_gemm_bias = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_gemm_bias_add = "stablehlo.add"(%x_gemm, %x_gemm_bias) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Subtract: x = x - subtract
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_sub = "stablehlo.subtract"(%x_gemm_bias_add, %subtract_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1, keepdim=True
  // mean = sum / dim_size
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %dim_size = "stablehlo.constant"() {value = dense<7> : tensor<i64>} : () -> tensor<i64>
  %dim_size_f32 = "stablehlo.constant"() {value = dense<7.0> : tensor<f32>} : () -> tensor<f32>

  %x_sum = "stablehlo.reduce"(%x_sub, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Broadcast sum back to shape [6x1] for division
  %x_sum_broadcast = "stablehlo.broadcast_in_dim"(%x_sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // Broadcast dim_size_f32 to [6x1]
  %dim_size_broadcast = "stablehlo.broadcast_in_dim"(%dim_size_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>

  // Compute mean = sum / dim_size
  %x_mean = "stablehlo.divide"(%x_sum_broadcast, %dim_size_broadcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  // LogSumExp: logsumexp over dim=1, keepdim=True
  // Since x_mean shape is [6x1], logsumexp over dim=1 is just log(exp(x_mean)) = x_mean
  // But to follow the spec, we do it explicitly:
  // logsumexp(x) = log(sum(exp(x)))
  // Here x_mean shape is [6x1], so sum over dim=1 is sum over size 1, so sum = exp(x_mean)
  // So logsumexp = x_mean

  // Compute exp(x_mean)
  %x_exp = "stablehlo.exponential"(%x_mean) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // sum over dim=1 (size 1), so sum = x_exp itself
  // log of sum = log(x_exp) = x_mean
  %x_logsumexp = "stablehlo.log"(%x_exp) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // GELU: apply GELU elementwise on x_logsumexp
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
