  %sqrt_2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt_2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %x_div_sqrt2 = "stablehlo.divide"(%x_logsumexp, %sqrt_2_broadcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %x_erf = "chlo.erf"(%x_div_sqrt2) : (tensor<6x1xf32>) -> tensor<6x1xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_plus_erf = "stablehlo.add"(%one_broadcast, %x_erf) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %x_mul_half = "stablehlo.multiply"(%x_logsumexp, %half_broadcast) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>
  %gelu = "stablehlo.multiply"(%x_mul_half, %one_plus_erf) : (tensor<6x1xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  // ResidualAdd: x = gelu + original_x
  // gelu shape: [6x1], original_x shape: [6x7]
  // Broadcast gelu from [6x1] to [6x7]
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0>} : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %output = "stablehlo.add"(%gelu_broadcast, %original_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  return %output : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = add_value (tensor<7xf32>)
  // %arg1 = matmul.weight (tensor<7x7xf32>)
  // %arg2 = matmul.bias (tensor<7xf32>)
  // %arg3 = input x (tensor<6x7xf32>)

  // Perform matmul: x @ weight^T
  // weight shape: [7,7], we want to multiply input [6,7] by weight^T [7,7]
  // So transpose weight to [7,7] (actually same shape, but transpose swaps dims)
  %weight_t = stablehlo.transpose %arg1 {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul = stablehlo.dot_general %arg3, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<6x7xf32>

  // Add add_value: broadcast add_value (7) to (6x7)
  %add_value_broadcast = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %add = stablehlo.add %matmul_bias, %add_value_broadcast : tensor<6x7xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %add : tensor<6x7xf32>
  %exp_neg = stablehlo.exponential %neg : tensor<6x7xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %exp_neg_plus_one = stablehlo.add %exp_neg, %one_broadcast : tensor<6x7xf32>
  %sigmoid = stablehlo.divide %one_broadcast, %exp_neg_plus_one : tensor<6x7xf32>
  %swish = stablehlo.multiply %add, %sigmoid : tensor<6x7xf32>

  // Tanh
  %tanh = stablehlo.tanh %swish : tensor<6x7xf32>

  // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = stablehlo.broadcast_in_dim %half {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %one_broadcast2 = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %sqrt2_broadcast = stablehlo.broadcast_in_dim %sqrt2 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %div = stablehlo.divide %tanh, %sqrt2_broadcast : tensor<6x7xf32>
  %erf = "chlo.erf"(%div) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %one_broadcast2, %erf : tensor<6x7xf32>
  %gelu = stablehlo.multiply %tanh, %half_broadcast : tensor<6x7xf32>
  %gelu = stablehlo.multiply %gelu, %one_plus_erf : tensor<6x7xf32>

  // Hardtanh with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %min_val_broadcast = stablehlo.broadcast_in_dim %min_val {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %max_val_broadcast = stablehlo.broadcast_in_dim %max_val {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %clamped_min = stablehlo.maximum %gelu, %min_val_broadcast : tensor<6x7xf32>
  %hardtanh = stablehlo.minimum %clamped_min, %max_val_broadcast : tensor<6x7xf32>

  return %hardtanh : tensor<6x7xf32>
}

