func.func @main(%arg0: tensor<6x6x3x3xf32>, %arg1: tensor<8x6x7x8xf32>) -> tensor<8x6x9x10xf32> {
  // %arg0: weight tensor of shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=3]
  // %arg1: input tensor of shape [batch=8, in_channels=6, height=7, width=8]

  // Transposed convolution in PyTorch is implemented as a convolution with the kernel reversed on spatial dims,
  // swapping input/output channels, and appropriate padding and stride.
  //
  // Given:
  //   weight shape: [in_channels, out_channels, kh, kw] = [6, 6, 3, 3]
  //   input shape: [batch, in_channels, h_in, w_in] = [8, 6, 7, 8]
  //   stride=1, padding=0, output_padding=0, groups=1
  //
  // The transposed conv2d output shape is:
  //   h_out = (h_in - 1) * stride - 2*padding + kh + output_padding = (7-1)*1 - 0 + 3 + 0 = 9
  //   w_out = (8-1)*1 - 0 + 3 + 0 = 10
  //
  // StableHLO convolution expects:
  //   lhs = input: [batch, feature, spatial...]
  //   rhs = kernel: [out_feature, in_feature/groups, spatial...]
  //
  // For transposed conv, we do a convolution with:
  //   lhs = input
  //   rhs = reversed kernel spatially, with swapped in/out channels dims
  //
  // So we must:
  // 1) Reverse kernel spatial dims (dims 2 and 3)
  // 2) Transpose kernel dims from [in_channels, out_channels, kh, kw] to [out_channels, in_channels, kh, kw]
  //
  // Then perform convolution with:
  //   window_strides = [1,1]
  //   padding = [[0,0],[0,0]] (no padding)
  //   lhs_dilation = [1,1]
  //   rhs_dilation = [1,1]
  //   dimension_numbers = [b,f,h,w]x[o,i,kh,kw]->[b,f,h,w]
  //   feature_group_count = 1
  //
  // The output shape will be [8,6,9,10] as required.

  // Step 1: Reverse kernel spatial dims (dims 2 and 3)
  %rev_kernel_spatial = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 2: Transpose kernel dims from [in_channels, out_channels, kh, kw] to [out_channels, in_channels, kh, kw]
  // We want to permute dims: 0->1, 1->0, 2->2, 3->3
  %kernel_transposed = "stablehlo.transpose"(%rev_kernel_spatial) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x6x3x3xf32>) -> tensor<6x6x3x3xf32>

  // Step 3: Perform convolution
  %conv = "stablehlo.convolution"(%arg1, %kernel_transposed) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x7x8xf32>, tensor<6x6x3x3xf32>) -> tensor<8x6x9x10xf32>

  return %conv : tensor<8x6x9x10xf32>
}

// conv dimension_numbers attribute
// input dims: [b, f, h, w] = [0,1,2,3]
// kernel dims: [o, i, kh, kw] = [0,1,2,3]
// output dims: [b, f, h, w] = [0,1,2,3]
//
// This attribute is defined as a symbol attribute below:
