func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
  // InstanceNorm2d forward:
  // input shape: [N=6, C=7, H=8, W=8]
  // Compute mean and variance per instance per channel over spatial dims (H,W).
  // mean shape: [6,7,1,1]
  // variance shape: [6,7,1,1]
  // epsilon = 1e-5 for numerical stability

  // Step 1: Compute mean over dims 2,3 (H,W)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1e5 = stablehlo.constant dense<0.00001> : tensor<f32>

  // Reduce sum over dims 2,3
  %mean_sum = stablehlo.reduce(%arg0, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute divisor = 8*8 = 64 as f32 scalar tensor
  %c64 = stablehlo.constant dense<64.0> : tensor<f32>

  // Broadcast divisor to shape [6,7]
  %divisor_bcast = stablehlo.broadcast_in_dim %c64 
    {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x7xf32>

  // mean = mean_sum / divisor
  %mean = stablehlo.divide %mean_sum, %divisor_bcast : tensor<6x7xf32>

  // Reshape mean to [6,7,1,1] for broadcasting
  %mean_reshaped = stablehlo.reshape %mean : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Step 2: Compute variance
  // variance = mean((x - mean)^2) over dims 2,3

  // Broadcast mean to input shape [6,7,8,8]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_reshaped 
    {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  // Compute (x - mean)
  %diff = stablehlo.subtract %arg0, %mean_bcast : tensor<6x7x8x8xf32>

  // Compute (x - mean)^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7x8x8xf32>

  // Reduce sum of squared differences over dims 2,3
  %var_sum = stablehlo.reduce(%diff_sq, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // variance = var_sum / divisor
  %variance = stablehlo.divide %var_sum, %divisor_bcast : tensor<6x7xf32>

  // Reshape variance to [6,7,1,1]
  %variance_reshaped = stablehlo.reshape %variance : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Step 3: Compute inv_std = 1 / sqrt(variance + epsilon)
  %var_eps = stablehlo.add %variance_reshaped, %c1e5 : tensor<6x7x1x1xf32>
  %sqrt_var_eps = stablehlo.sqrt %var_eps : tensor<6x7x1x1xf32>
  %inv_std = stablehlo.divide %c1, %sqrt_var_eps : tensor<6x7x1x1xf32>
  // Note: %c1 not defined yet, define it now:
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>

  // Step 4: Normalize: (x - mean) * inv_std
  %normalized = stablehlo.multiply %diff, %inv_std : tensor<6x7x8x8xf32>

  // InstanceNorm2d has affine=False by default, so no scale or bias applied.
  // Return normalized output
  stablehlo.return %normalized : tensor<6x7x8x8xf32>
}

