func.func @main(%conv_weight: tensor<7x7x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Transpose conv_weight from (in_channels=7, out_channels=7, kH=3, kW=3)
  // to (out_channels=7, in_channels=7, kH=3, kW=3) for stablehlo.convolution rhs
  %weight_reshaped = stablehlo.reshape %conv_weight : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>
  %weight_transposed = "stablehlo.transpose"(%weight_reshaped) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<7x7x3x3xf32>) -> tensor<7x7x3x3xf32>

  // stablehlo.convolution expects input shape: [batch, feature, height, width]
  // input is already [6x7x6x6]
  // conv rhs shape: [out_channels, in_channels, kH, kW] = [7x7x3x3]
  // dimension_numbers: input [b,f,h,w], kernel [o,i,h,w], output [b,f,h,w]
  // stride=2, padding=1, output_padding=1 for ConvTranspose2d
  // ConvTranspose2d is implemented as a convolution with lhs_dilation=stride,
  // rhs_dilation=1, window_strides=1, and padding adjusted accordingly.
  // Calculate padding for conv_transpose:
  // padding = kernel_size - 1 - padding = 3 - 1 - 1 = 1
  // So padding = 1 on all sides
  // lhs_dilation = stride = 2
  // rhs_dilation = 1
  // window_strides = 1
  // feature_group_count = 1
  // batch_group_count = 1

