    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: conv output shape [6x7x12x12], bias shape [7]
  // Broadcast bias to [6x7x12x12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>
