  %mish = stablehlo.multiply %biased, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add add_value = 0.5
  %add_val = stablehlo.constant dense<0.5> : tensor<f32>
  %add_val_broadcast = "stablehlo.broadcast_in_dim"(%add_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %mish_plus = stablehlo.add %mish, %add_val_broadcast : tensor<6x7x12x12xf32>

  // Hardtanh activation with min_val=-1, max_val=1
  %min_val = stablehlo.constant dense<-1.0> : tensor<f32>
  %max_val = stablehlo.constant dense<1.0> : tensor<f32>
  %min_broadcast = "stablehlo.broadcast_in_dim"(%min_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
