  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale_val) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %hardtanh, %scale_broadcast : tensor<6x7x12x12xf32>

  return %scaled : tensor<6x7x12x12xf32>
}

