  %gamma_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %beta_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = "stablehlo.multiply"(%normalized_2d, %gamma_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %gn_out = "stablehlo.add"(%scaled, %beta_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // 3) LeakyReLU with negative_slope=0.01
  %zero_tensor = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero_tensor) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  // Compare gn_out >= 0
  %cond = "stablehlo.compare"(%gn_out, %zero_broadcast) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xi1>
  // Compute negative_slope * gn_out
  %neg_slope = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>
  %neg_slope_broadcast = "stablehlo.broadcast_in_dim"(%neg_slope) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<16x16xf32>
  %neg_scaled = "stablehlo.multiply"(%gn_out, %neg_slope_broadcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Select: if cond then gn_out else neg_scaled
  %leaky_relu_out = "stablehlo.select"(%cond, %gn_out, %neg_scaled) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // 4) Add x + x (element-wise sum)
  %out = "stablehlo.add"(%leaky_relu_out, %leaky_relu_out) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  return %out : tensor<16x16xf32>
}

