  // %arg0 = scaling_factor (16x1x1x1)
  // %arg1 = bias (16x1x1x1)
  // %arg2 = conv.weight (16x3x3x3x3)
  // %arg3 = conv.bias (16)
  // %arg4 = input (6x3x16x7x7)

  // Convolution dimension numbers for 3D conv:
  // input dims: [b, f, d, h, w] = [0,1,2,3,4]
  // kernel dims: [o, i, kd, kh, kw] = [0,1,2,3,4]
  // output dims: [b, f, d, h, w] = [0,1,2,3,4]
  // feature_group_count = 1, batch_group_count = 1

  %conv = "stablehlo.convolution"(%arg4, %arg2) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
