  // Add conv.bias (16) to conv output (6x16x14x5x5)
  // Broadcast conv.bias from (16) to (6x16x14x5x5)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<6x16x14x5x5xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast : tensor<6x16x14x5x5xf32>

  // Broadcast scaling_factor (16x1x1x1) to (6x16x14x5x5)
  // scaling_factor dims: [16,1,1,1] -> broadcast to [6,16,14,5,5]
  // broadcast_dimensions = [1,2,3,4] for scaling_factor dims 0..3? No, scaling_factor rank=4, output rank=5
  // The input scaling_factor is tensor<16x1x1x1>, rank=4
  // Output is rank=5: [6,16,14,5,5]
  // We want to broadcast scaling_factor over batch dim (0) and spatial dims (2,3,4)
  // So broadcast_dimensions = [1,2,3,4]
  %scaling_factor_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  // Multiply conv_bias_added by scaling_factor_broadcast
  %scaled = stablehlo.multiply %conv_bias_added, %scaling_factor_broadcast : tensor<6x16x14x5x5xf32>

