  // broadcast_dimensions = [1,2,3,4]
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<16x1x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  // Multiply tanh output by bias_broadcast2
  %biased = stablehlo.multiply %tanh, %bias_broadcast2 : tensor<6x16x14x5x5xf32>

  // Apply sigmoid (logistic)
  %sigmoid = stablehlo.logistic %biased : tensor<6x16x14x5x5xf32>

  return %sigmoid : tensor<6x16x14x5x5xf32>
}

