  %c_one = stablehlo.constant dense<1.0> : tensor<f32>
  %c_sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // approx sqrt(2)

  // Broadcast constants to input shape
  %half = stablehlo.broadcast_in_dim %c_half {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %one = stablehlo.broadcast_in_dim %c_one {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %sqrt2 = stablehlo.broadcast_in_dim %c_sqrt2 {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>

  // x / sqrt(2)
  %div = stablehlo.divide %arg0, %sqrt2 : tensor<6x7xf32>

  // erf(x / sqrt(2))
  %erf = chlo.erf %div : tensor<6x7xf32>

  // 1 + erf(...)
  %add = stablehlo.add %one, %erf : tensor<6x7xf32>

  // x * (1 + erf(...))
  %mul1 = stablehlo.multiply %arg0, %add : tensor<6x7xf32>

  // 0.5 * x * (1 + erf(...))
  %result = stablehlo.multiply %half, %mul1 : tensor<6x7xf32>

  return %result : tensor<6x7xf32>
}

