func.func @main(%arg0: tensor<7x6x4x4xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x7x7xf32>) -> tensor<6x6x16x16xf32> {
  // %arg0: conv_transpose.weight: tensor<7x6x4x4xf32> (in_channels=7, out_channels=6, kernel=4x4)
  // %arg1: conv_transpose.bias: tensor<6xf32>
  // %arg2: input: tensor<6x7x7x7xf32> (batch=6, in_channels=7, height=7, width=7)

  // We want to perform ConvTranspose2d with:
  // in_channels=7, out_channels=6, kernel=4, stride=2
  // PyTorch ConvTranspose2d weight shape: (in_channels, out_channels, kH, kW) = (7,6,4,4)
  // StableHLO convolution expects rhs shape: (output_channels, input_channels/groups, kH, kW)
  // So we must reshape/transpose %arg0 from (7,6,4,4) to (6,7,4,4)

  // Transpose %arg0 from [7,6,4,4] -> [6,7,4,4]
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c3 = stablehlo.constant dense<3> : tensor<i64>
  %weight_perm = stablehlo.constant dense<[1, 0, 2, 3]> : tensor<4xi64>
  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = [1, 0, 2, 3]} : (tensor<7x6x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Perform convolution with dimension_numbers:
  // input: batch=0, feature=1, spatial=2,3
  // kernel: output_feature=0, input_feature=1, spatial=2,3
  // output: batch=0, feature=1, spatial=2,3
  // stride=2, padding=1 on each side (to get output size 16 from input 7 and kernel 4)
  // lhs_dilation=1, rhs_dilation=1
  // feature_group_count=1, batch_group_count=1

  %conv = "stablehlo.convolution"(%arg2, %weight_transposed) {
    window_strides = array<i64: 2, 2>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x7x7xf32>, tensor<6x7x4x4xf32>) -> tensor<6x6x16x16xf32>

  // Add bias %arg1 (shape [6]) to conv output (shape [6x6x16x16])
  // Broadcast bias to [batch=6, feature=6, height=16, width=16]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x16x16xf32>
  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x16x16xf32>

  // Add add_value = 0.5 (constant scalar)
  %add_val = stablehlo.constant dense<0.5> : tensor<f32>
  %add_val_broadcast = "stablehlo.broadcast_in_dim"(%add_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %add_added = stablehlo.add %add_bias, %add_val_broadcast : tensor<6x6x16x16xf32>

  // Compute minimum with 0.0 (elementwise min(x, 0))
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %min0 = stablehlo.minimum %add_added, %zero_broadcast : tensor<6x6x16x16xf32>

  // Apply GELU: gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %x_div_sqrt2 = stablehlo.divide %min0, %sqrt2_broadcast : tensor<6x6x16x16xf32>

  // Compute erf(x / sqrt(2))
  %erf = "chlo.erf"(%x_div_sqrt2) : (tensor<6x6x16x16xf32>) -> tensor<6x6x16x16xf32>

  // Compute 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<6x6x16x16xf32>

  // Compute 0.5 * x
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %half_x = stablehlo.multiply %half_broadcast, %min0 : tensor<6x6x16x16xf32>

  // GELU output = 0.5 * x * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x6x16x16xf32>

  // Multiply by multiply_value = 2.0
  %mul_val = stablehlo.constant dense<2.0> : tensor<f32>
  %mul_val_broadcast = "stablehlo.broadcast_in_dim"(%mul_val) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x16x16xf32>
  %output = stablehlo.multiply %gelu, %mul_val_broadcast : tensor<6x6x16x16xf32>

  return %output : tensor<6x6x16x16xf32>
}

