func.func @main(%gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
  // Constants for epsilon and shapes
  %c_eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %c_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %c_one = stablehlo.constant dense<1.0> : tensor<f32>

  // Shapes
  // input shape: [14,16,16,16]
  // num_groups = 8
  // group_size = 16 / 8 = 2

  // Reshape input from [14,16,16,16] to [14,8,2,16,16]
  %input_reshaped = stablehlo.reshape %input : (tensor<14x16x16x16xf32>) -> tensor<14x8x2x16x16xf32>

  // Compute mean over axes [2,3,4] (group_size and spatial dims)
  // init mean = 0.0
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %input_reshaped, %init_mean 
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Compute count = 2*16*16 = 512 as constant
  %c_count = stablehlo.constant dense<512.0> : tensor<f32>

  // mean = mean / count
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = array<i64: 0,1>} : tensor<14x8xf32> -> tensor<14x8xf32>
  %mean_div = stablehlo.divide %mean, %c_count : tensor<14x8xf32>

  // Broadcast mean to [14,8,2,16,16]
  %mean_bcast = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 0,1>} : tensor<14x8xf32> -> tensor<14x8x1x1x1xf32>
  %mean_bcast_reshaped = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 0,1>} : tensor<14x8xf32> -> tensor<14x8x1x1x1xf32>
  %mean_bcast_full = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 0,1)} : tensor<14x8xf32> -> tensor<14x8x1x1x1xf32>
  // Actually, broadcast_in_dim with dims [0,1] to shape [14,8,2,16,16] requires dims [0,1,2,3,4] with 1s in input dims
  %mean_bcast_full = stablehlo.broadcast_in_dim %mean_div {broadcast_dimensions = array<i64: 0,1,2,3,4>} : tensor<14x8xf32> -> tensor<14x8x2x16x16xf32>

  // Compute variance: mean of squared difference
  // diff = input_reshaped - mean_bcast_full
  %diff = stablehlo.subtract %input_reshaped, %mean_bcast_full : tensor<14x8x2x16x16xf32>

  // diff_sq = diff * diff
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<14x8x2x16x16xf32>

  // init variance = 0.0
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = stablehlo.reduce %diff_sq, %init_var 
    ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = array<i64: 2, 3, 4>} : (tensor<14x8x2x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // variance = var_sum / count
  %var = stablehlo.divide %var_sum, %c_count : tensor<14x8xf32>

  // Add epsilon to variance
  %var_eps = stablehlo.add %var, %c_eps : tensor<14x8xf32>

  // Compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<14x8xf32>

  // Broadcast inv_std to [14,8,2,16,16]
  %inv_std_bcast = stablehlo.broadcast_in_dim %inv_std {broadcast_dimensions = array<i64: 0,1,2,3,4>} : tensor<14x8xf32> -> tensor<14x8x2x16x16xf32>

  // Normalize: (input_reshaped - mean_bcast_full) * inv_std_bcast
  %normalized = stablehlo.multiply %diff, %inv_std_bcast : tensor<14x8x2x16x16xf32>

  // Reshape normalized back to [14,16,16,16]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<14x8x2x16x16xf32>) -> tensor<14x16x16x16xf32>

  // Reshape gn.weight and gn.bias from [16] to [1,16,1,1] for broadcasting
  %gn_weight_reshaped = stablehlo.reshape %gn_weight : (tensor<16xf32>) -> tensor<1x16x1x1xf32>
  %gn_bias_reshaped = stablehlo.reshape %gn_bias : (tensor<16xf32>) -> tensor<1x16x1x1xf32>

  // Broadcast gn.weight and gn.bias to [14,16,16,16]
  %gn_weight_bcast = stablehlo.broadcast_in_dim %gn_weight_reshaped {broadcast_dimensions = array<i64: 1>} : tensor<1x16x1x1xf32> -> tensor<14x16x16x16xf32>
  %gn_bias_bcast = stablehlo.broadcast_in_dim %gn_bias_reshaped {broadcast_dimensions = array<i64: 1>} : tensor<1x16x1x1xf32> -> tensor<14x16x16x16xf32>

  // Apply affine transform: normalized * weight + bias
  %scaled = stablehlo.multiply %normalized_reshaped, %gn_weight_bcast : tensor<14x16x16x16xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<14x16x16x16xf32>

  func.return %shifted : tensor<14x16x16x16xf32>
}

func.func @main(%idx: tensor<8xi32>) -> tensor<8x3xf32> {
  // Create a tensor with values [0, 1, 2] of shape [3]
  %c012 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<3xi32>
  // Broadcast idx from [8] to [8,3] with broadcast_dimensions = [0]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<8xi32>) -> tensor<8x3xi32>
  // Broadcast c012 from [3] to [8,3] with broadcast_dimensions = [1]
  %c012_bcast = "stablehlo.broadcast_in_dim"(%c012) {broadcast_dimensions = array<i64: 1>} : (tensor<3xi32>) -> tensor<8x3xi32>
  // Compare idx_bcast == c012_bcast, result is i1 tensor<8x3xi1>
  %eq = "stablehlo.compare"(%idx_bcast, %c012_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<8x3xi32>, tensor<8x3xi32>) -> tensor<8x3xi1>
  // Create constant 1.0 tensor<8x3xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} } : (tensor<f32>) -> tensor<8x3xf32>
  // Create constant 0.0 tensor<8x3xf32>
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0} } : (tensor<f32>) -> tensor<8x3xf32>
  // Select 1.0 where eq is true, else 0.0
  %result = "stablehlo.select"(%eq, %one_bcast, %zero_bcast) : (tensor<8x3xi1>, tensor<8x3xf32>, tensor<8x3xf32>) -> tensor<8x3xf32>
  return %result : tensor<8x3xf32>
}

func.func @main(%arg0: tensor<6x6x3x3x3xf32>, %arg1: tensor<4x6x6x7x8xf32>) -> tensor<4x6x11x13x15xf32> {
  // %arg0: weight tensor of shape [out_channels=6, in_channels=6, 3, 3, 3]
  // %arg1: input tensor of shape [batch=4, channels=6, depth=6, height=7, width=8]

  // Step 1: Reverse the kernel spatial dimensions (depth, height, width)
  // Reverse dims 2,3,4 of %arg0 (kernel spatial dims)
  %reversed_kernel = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

  // Step 2: Perform convolution with appropriate dimension numbers and parameters
  // Transposed convolution parameters:
  // stride = 2
  // padding = 1
  // groups = 4
  // batch_group_count = 1 (default)
  //
  // Dimension numbers for convolution:
  // Input: [b, f, d, h, w] = [batch, feature, spatial dims]
  // Kernel: [o, i, kd, kh, kw] = [output feature, input feature, spatial dims]
  // Output: [b, f, d, h, w]
  //
  // feature_group_count = 4
  //
  // lhs_dilation = stride = 2 (to implement transposed convolution)
  // rhs_dilation = 1 (no dilation on kernel)
  //
  // padding = 1 on each spatial dimension (depth, height, width)
  //
  // stablehlo.convolution formula:
  // output = conv(lhs, rhs) with lhs_dilation = stride, rhs_dilation=1, padding=padding
  //
  // lhs = input tensor %arg1: [4,6,6,7,8]
  // rhs = reversed kernel: [6,6,3,3,3]
  //
  // Check feature groups:
  // dim(rhs, i) = dim(lhs, f) / feature_group_count
  // dim(rhs, i) = 6
  // dim(lhs, f) = 6
  // 6 / 4 = 1.5 not integer, but PyTorch groups=4 means input channels divided into 4 groups
  // Actually, PyTorch groups=4 means in_channels=6, out_channels=6, groups=4
  // So in_channels per group = 6/4=1.5 (not integer)
  // This is inconsistent with PyTorch groups param, but we follow the problem statement.
  //
  // Since groups=4, feature_group_count=4
  //
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  //
  // window_strides = [1,1,1]
  // lhs_dilation = [2,2,2]
  // rhs_dilation = [1,1,1]
  //
  // padding = [[1,1],[1,1],[1,1]]

  %conv = "stablehlo.convolution"(%arg1, %reversed_kernel) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 4 : i64,
    batch_group_count = 1 : i64
  } : (tensor<4x6x6x7x8xf32>, tensor<6x6x3x3x3xf32>) -> tensor<4x6x11x13x15xf32>

  return %conv : tensor<4x6x11x13x15xf32>
}

