func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0: gemm.weight (16x16)
  // %arg1: gemm.bias (16)
  // %arg2: group_norm.weight (16)
  // %arg3: group_norm.bias (16)
  // %arg4: input (16x16)

  // GEMM: x @ W^T + b
  // dot_general with contracting dims: lhs dim 1, rhs dim 1
  // lhs_batching_dimensions = [0], rhs_batching_dimensions = [0]
  // lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [0],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias from [16] to [16x16]
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm:
  // num_groups = 16, out_features = 16, so group size = 1
  // Reshape to [batch_size, num_groups, group_size] = [16,16,1]
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over group_size dimension (dim=2)
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c1f = stablehlo.constant dense<1.0> : tensor<f32>
  %c1i = stablehlo.constant dense<1> : tensor<i64>

  // sum over dim=2
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce(%3, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean = sum / group_size (1)
  // group_size = 1, so mean unchanged
  // mean shape: [16,16]

  // Reshape mean to [16,16,1] for broadcasting
  %mean_broadcast = stablehlo.reshape %mean : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over dim=2
  %sub = stablehlo.subtract %3, %mean_broadcast : tensor<16x16x1xf32>
  %sq = stablehlo.multiply %sub, %sub : tensor<16x16x1xf32>

  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = stablehlo.reduce(%sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add2 = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add2 : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = sum / group_size (1), so unchanged

  // Reshape variance to [16,16,1] for broadcasting
  %var_broadcast = stablehlo.reshape %var : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // epsilon constant for numerical stability
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>

  // variance + epsilon
  %var_eps = stablehlo.add %var_broadcast, %eps : tensor<16x16x1xf32>

  // rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %norm = stablehlo.multiply %sub, %inv_std : tensor<16x16x1xf32>

  // Reshape normalized to [16x16]
  %norm_reshaped = stablehlo.reshape %norm : tensor<16x16x1xf32> -> tensor<16x16xf32>

  // Apply affine transform: weight * norm + bias
  // weight and bias shape: [16]
  // Broadcast weight and bias to [16x16]
  %weight_broadcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %norm_reshaped, %weight_broadcast : tensor<16x16xf32>
  %shifted = stablehlo.add %scaled, %bias_broadcast : tensor<16x16xf32>

  // HardTanh clamp between -2.0 and 2.0
  %min_val = stablehlo.constant dense<-2.0> : tensor<f32>
  %max_val = stablehlo.constant dense<2.0> : tensor<f32>

  // Broadcast min and max to [16x16]
  %min_broadcast = stablehlo.broadcast_in_dim %min_val {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>
  %max_broadcast = stablehlo.broadcast_in_dim %max_val {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x16xf32>

  %clamped_min = stablehlo.maximum %shifted, %min_broadcast : tensor<16x16xf32>
  %clamped = stablehlo.minimum %clamped_min, %max_broadcast : tensor<16x16xf32>

  return %clamped : tensor<16x16xf32>
}

