func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute diff = predictions - targets
  %diff = "stablehlo.subtract"(%arg0, %arg1) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute abs_diff = abs(diff)
  %abs_diff = "stablehlo.abs"(%diff) : (tensor<6x6xf32>) -> tensor<6x6xf32>

  // Create constant 1.0 for comparison
  %c1 = "stablehlo.constant"() {value = dense<1.000000e+00> : tensor<f32>} : () -> tensor<f32>
  // Broadcast c1 to shape 6x6
  %c1_b = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cond = "stablehlo.compare"(%abs_diff, %c1_b) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute squared term: 0.5 * diff^2
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>
  %c05 = "stablehlo.constant"() {value = dense<5.000000e-01> : tensor<f32>} : () -> tensor<f32>
  %c05_b = "stablehlo.broadcast_in_dim"(%c05) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %sq_term = "stablehlo.multiply"(%c05_b, %diff_sq) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute linear term: abs_diff - 0.5
  %c05_b2 = %c05_b  // reuse broadcasted 0.5
  %lin_term = "stablehlo.subtract"(%abs_diff, %c05_b2) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Select between sq_term and lin_term based on cond
  %loss_per_element = "stablehlo.select"(%cond, %sq_term, %lin_term) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements of loss_per_element
  %init = "stablehlo.constant"() {value = dense<0.000000e+00> : tensor<f32>} : () -> tensor<f32>
  %sum_loss = "stablehlo.reduce"(%loss_per_element, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
    }
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean by dividing sum_loss by total number of elements (36)
  %c36 = "stablehlo.constant"() {value = dense<3.600000e+01> : tensor<f32>} : () -> tensor<f32>
  %mean_loss = "stablehlo.divide"(%sum_loss, %c36) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  "stablehlo.return"(%mean_loss) : tensor<f32>
}

