}

func.func @main(%x: tensor<3x8xf32>) -> tensor<3x8xf32> {
  %c0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %c1 = "stablehlo.constant"() {value = dense<1e-6> : tensor<f32>} : () -> tensor<f32>
  // square each element: x^2
  %x_sq = "stablehlo.multiply"(%x, %x) : (tensor<3x8xf32>, tensor<3x8xf32>) -> tensor<3x8xf32>
  // sum over axis 1 (columns) to get sum_k x[i,k]^2, shape: tensor<3xf32>
  %init = "stablehlo.broadcast_in_dim"(%c0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<3xf32>
  %sum_sq = "stablehlo.reduce"(%x_sq, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<3xf32>) -> tensor<3xf32>
  // add epsilon for numerical stability
  %sum_sq_eps = "stablehlo.add"(%sum_sq, %c1) : (tensor<3xf32>, tensor<f32>) -> tensor<3xf32>
  // sqrt of sum of squares
  %norm = "stablehlo.sqrt" %sum_sq_eps : tensor<3xf32>
  // broadcast norm to shape 3x8 for division
  %norm_bcast = "stablehlo.broadcast_in_dim"(%norm) {broadcast_dimensions = array<i64: 0} : (tensor<3xf32>) -> tensor<3x8xf32>
  // divide x by norm
  %out = "stablehlo.divide"(%x, %norm_bcast) : (tensor<3x8xf32>, tensor<3x8xf32>) -> tensor<3x8xf32>
  "stablehlo.return"(%out) : tensor<3x8xf32>
}

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<16x6x8x8xf32>) -> tensor<16x1xf32> {
  // Transpose conv_transpose.weight from (in_channels=6, out_channels=7, 3, 3)
  // to (out_channels=7, in_channels=6, 3, 3) for convolution rhs.
  %c0 = stablehlo.constant dense<0> : tensor<i64>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %c2 = stablehlo.constant dense<2> : tensor<i64>
  %c3 = stablehlo.constant dense<3> : tensor<i64>
  %c4 = stablehlo.constant dense<4> : tensor<i64>

  // Permute dimensions of %arg1 from (6,7,3,3) to (7,6,3,3)
  %perm = stablehlo.constant dense<[1, 0, 2, 3]> : tensor<4xi64>
  %conv_rhs = stablehlo.transpose %arg1, %perm : (tensor<6x7x3x3xf32>, tensor<4xi64>) -> tensor<7x6x3x3xf32>

  // Perform convolution with dimension_numbers for ConvTranspose2d:
  // Input: (batch=16, in_channels=6, height=8, width=8)
  // Kernel: (out_channels=7, in_channels=6, 3, 3)
  // Output: (batch=16, out_channels=7, height_out, width_out)
  // Use stride=1, padding=0, dilation=1, feature_group_count=1, batch_group_count=1
  // dimension_numbers = [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
  %c_stride = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_padding = stablehlo.constant dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>
  %c_dilation = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %conv_out = stablehlo.convolution %arg3, %conv_rhs {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x6x6xf32>

  // Global average pooling: mean over spatial dims (2,3) with keepdim=True
  // mean = sum / (height * width) = sum / 36
  %c36 = stablehlo.constant dense<36.0> : tensor<f32>
  %init_sum = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_spatial = stablehlo.reduce(%conv_out, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x6x6xf32>, tensor<f32>) -> tensor<16x7xf32>

  // Reshape sum_spatial from (16,7) to (16,7,1,1) to keep dims
  %sum_spatial_reshaped = stablehlo.reshape %sum_spatial : tensor<16x7xf32> -> tensor<16x7x1x1xf32>

  // Divide by 36.0 to get mean
  %c36_bcast = stablehlo.broadcast_in_dim %c36 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x7x1x1xf32>
  %mean = stablehlo.divide %sum_spatial_reshaped, %c36_bcast : tensor<16x7x1x1xf32>

  // Add bias (%arg0) broadcasted to (16x7x1x1)
  %bias_bcast = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<16x7x1x1xf32>
  %biased = stablehlo.add %mean, %bias_bcast : tensor<16x7x1x1xf32>

  // Compute logsumexp over dim=1 (channels), keepdim=True
  // logsumexp(x) = log(sum(exp(x)))
  // Step 1: exp
  %exp = stablehlo.exponential %biased : tensor<16x7x1x1xf32>

  // Step 2: sum over dim=1, keepdim=True
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce(%exp, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x1x1x1xf32>

  // Step 3: log
  %logsumexp = stablehlo.log %sum_exp : tensor<16x1x1x1xf32>

  // Sum over dims (2,3) (height and width), dims are size 1, so sum is identity but keep for correctness
  %init_zero2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_hw = stablehlo.reduce(%logsumexp, %init_zero2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): 
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x1x1x1xf32>, tensor<f32>) -> tensor<16x1xf32>

  // Multiply by 10.0
  %c10 = stablehlo.constant dense<10.0> : tensor<f32>
  %c10_bcast = stablehlo.broadcast_in_dim %c10 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x1xf32>
  %result = stablehlo.multiply %sum_hw, %c10_bcast : tensor<16x1xf32>

  // Return result
  return %result : tensor<16x1xf32>
}

func.func @main(%x: tensor<2x5xf32>, %y: tensor<3x5xf32>) -> tensor<2x3xf32> {
  // Broadcast x from [2,5] to [2,3,5] by adding a new dim at position 1
  %x_broadcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0, 2>} : (tensor<2x5xf32>) -> tensor<2x3x5xf32>
  // Broadcast y from [3,5] to [2,3,5] by adding a new dim at position 0
