  // Square the difference
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<2x3x5xf32>, tensor<2x3x5xf32>) -> tensor<2x3x5xf32>
  // Create zero constant scalar for reduction init
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  // Reduce sum over last dimension (dimension 2)
  %result = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<2x3x5xf32>, tensor<f32>) -> tensor<2x3xf32>
  "stablehlo.return"(%result) : tensor<2x3xf32>
}

