func.func @main(%conv_weight: tensor<7x3x3x3x3xf32>, %conv_bias: tensor<7xf32>, %input: tensor<6x3x7x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // Convolution dimension numbers for Conv3d:
  // input: [batch, feature, depth, height, width] = [b, f, 0, 1, 2]
  // kernel: [out_feature, in_feature, kd, kh, kw] = [o, i, 0, 1, 2]
  // output: [batch, feature, depth, height, width] = [b, f, 0, 1, 2]
  //
  // window_strides = [1,1,1]
  // padding = 0 (valid convolution)
  // lhs_dilation = [1,1,1]
  // rhs_dilation = [1,1,1]
  // feature_group_count = 1
  // batch_group_count = 1

  %zero_f32 = stablehlo.constant dense<0.000000e+00> : tensor<f32>

  // Perform convolution: input (6x3x7x8x8), weight (7x3x3x3x3) -> output (6x7x5x6x6)
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x7x8x8xf32>, tensor<7x3x3x3x3xf32>) -> tensor<6x7x5x6x6xf32>

  // Add bias: conv output shape (6x7x5x6x6), bias shape (7)
  // Broadcast bias to shape (6x7x5x6x6)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<1x7x1x1x1xf32>) -> tensor<6x7x5x6x6xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast_reshaped : tensor<6x7x5x6x6xf32>

  // Apply minimum reduction along dimension 2 (depth dimension after conv)
  // dimension 2 corresponds to the depth dimension (size 5)
  // Initial value for minimum reduction is +inf
  %inf = stablehlo.constant dense<0x7F800000> : tensor<f32>
  %init_min = stablehlo.broadcast_in_dim %inf {broadcast_dimensions = array<i64: >} : () -> tensor<f32>
  %min_reduce = "stablehlo.reduce"(%conv_bias_added, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min_val = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%min_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x5x6x6xf32>, tensor<f32>) -> tensor<6x7x6x6xf32>

  // Apply softmax along dimension 1 (channel dimension)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // Steps:
  // 1) max along dim=1
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>
  %init_max = stablehlo.broadcast_in_dim %neg_inf {broadcast_dimensions = array<i64: >} : () -> tensor<f32>
  %max_reduce = "stablehlo.reduce"(%min_reduce, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // 2) subtract max from input (broadcast max)
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max_reduce) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x6x6xf32>) -> tensor<6x7x6x6xf32>
  %shifted = stablehlo.subtract %min_reduce, %max_broadcast : tensor<6x7x6x6xf32>

  // 3) exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7x6x6xf32>

  // 4) sum exp along dim=1
  %zero = stablehlo.constant dense<0.000000e+00> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = array<i64: >} : () -> tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum_val = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // 5) divide exp_shifted by sum_exp (broadcast sum_exp)
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_broadcast : tensor<6x7x6x6xf32>

  return %softmax : tensor<6x7x6x6xf32>
}

