func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x8x8x8xf32>) -> tensor<6x7x6x6xf32> {
  // %arg0: conv.weight (out_channels=7, in_channels=8, kernel_h=3, kernel_w=3)
  // %arg1: conv.bias (7)
  // %arg2: input (batch=6, in_channels=8, height=8, width=8)

  // Convolution dimension numbers:
  // input: [b, f, h, w] = [6, 8, 8, 8]
  // kernel: [o, i, kh, kw] = [7, 8, 3, 3]
  // output: [b, f, h_out, w_out] = [6, 7, 6, 6]
