    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Subtract subtract_value_1 = 0.5
  %c_sub1 = stablehlo.constant dense<0.5> : tensor<f32>
  %c_sub1_bcast = "stablehlo.broadcast_in_dim"(%c_sub1) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %sub1 = stablehlo.subtract %conv_bias, %c_sub1_bcast : tensor<6x7x6x6xf32>

  // Subtract subtract_value_2 = 0.2
  %c_sub2 = stablehlo.constant dense<0.2> : tensor<f32>
  %c_sub2_bcast = "stablehlo.broadcast_in_dim"(%c_sub2) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %sub2 = stablehlo.subtract %sub1, %c_sub2_bcast : tensor<6x7x6x6xf32>

  // Mish activation: x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))
  %exp = stablehlo.exponential %sub2 : tensor<6x7x6x6xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x6x6xf32>
  %exp_plus_one = stablehlo.add %exp, %one_bcast : tensor<6x7x6x6xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<6x7x6x6xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x6x6xf32>
  %mish = stablehlo.multiply %sub2, %tanh_softplus : tensor<6x7x6x6xf32>

  return %mish : tensor<6x7x6x6xf32>
}

// conv dimension_numbers attribute
// We define it here as a global attribute for reuse
// This is required by stablehlo.convolution op
// Format: #stablehlo.conv<[input dims]x[kernel dims]->[output dims]>
//
// input dims: [b, f, 0, 1]
// kernel dims: [o, i, 0, 1]
// output dims: [b, f, 0, 1]
//
// This attribute is referenced in the convolution op above.
#stablehlo.conv = {
  input_batch_dimension = 0 : i64,
  input_feature_dimension = 1 : i64,
  input_spatial_dimensions = array<i64: 2, 3>,
  kernel_output_feature_dimension = 0 : i64,
  kernel_input_feature_dimension = 1 : i64,
  kernel_spatial_dimensions = array<i64: 2, 3>,
  output_batch_dimension = 0 : i64,
  output_feature_dimension = 1 : i64,
  output_spatial_dimensions = array<i64: 2, 3>
}

