func.func @main(%arg0: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %cst_0_5 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %cst_1_0 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %cst_0_044715 = "stablehlo.constant"() {value = dense<0.044715> : tensor<f32>} : () -> tensor<f32>
  %cst_sqrt_2_over_pi = "stablehlo.constant"() {value = dense<0.7978845834732056> : tensor<f32>} : () -> tensor<f32>
  // Broadcast scalars to tensor<6x6xf32>
  %b_0_5 = "stablehlo.broadcast_in_dim"(%cst_0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %b_1_0 = "stablehlo.broadcast_in_dim"(%cst_1_0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %b_0_044715 = "stablehlo.broadcast_in_dim"(%cst_0_044715) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %b_sqrt_2_over_pi = "stablehlo.broadcast_in_dim"(%cst_sqrt_2_over_pi) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  // Compute x^3
  %x_cube = stablehlo.power %arg0, %b_1_0 : tensor<6x6xf32>
  %x_cube = stablehlo.multiply %arg0, %arg0 : tensor<6x6xf32>
  %x_cube = stablehlo.multiply %x_cube, %arg0 : tensor<6x6xf32>
  // Compute 0.044715 * x^3
  %term = stablehlo.multiply %b_0_044715, %x_cube : tensor<6x6xf32>
  // Compute x + 0.044715 * x^3
  %sum = stablehlo.add %arg0, %term : tensor<6x6xf32>
  // Compute sqrt(2/pi) * (x + 0.044715 * x^3)
  %scaled = stablehlo.multiply %b_sqrt_2_over_pi, %sum : tensor<6x6xf32>
  // Compute tanh(...)
  %tanh_val = stablehlo.tanh %scaled : tensor<6x6xf32>
  // Compute 1.0 + tanh(...)
  %one_plus_tanh = stablehlo.add %b_1_0, %tanh_val : tensor<6x6xf32>
  // Compute x * (1.0 + tanh(...))
  %mul = stablehlo.multiply %arg0, %one_plus_tanh : tensor<6x6xf32>
  // Compute 0.5 * x * (1.0 + tanh(...))
  %result = stablehlo.multiply %b_0_5, %mul : tensor<6x6xf32>
  return %result : tensor<6x6xf32>
}

