  // %matmul = %arg2 @input: tensor<6x7xf32>
  // %weight = %arg0 @weight: tensor<7x7xf32>
  // Perform matmul: x = input @ weight^T
  // Since PyTorch Linear uses weight shape (out_features, in_features),
  // and input shape (batch, in_features),
  // output = input @ weight^T
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %matmul = "stablehlo.dot_general"(%arg2, %weight_t) {
