  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x7xf32>
  %denominator = "stablehlo.add"(%one_broadcast, %exp_neg_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %sigmoid = "stablehlo.divide"(%one_broadcast, %denominator) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Multiply by scaling_factor = 2.0
  %scaling_factor = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %scaling_factor_broadcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<6x7xf32>
  %scaled = "stablehlo.multiply"(%sigmoid, %scaling_factor_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

