func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Compute log_softmax over dim=1 of %arg0 (predictions)
  // Step 1: Compute max_logits = max over dim=1 (shape: tensor<6xf32>)
  %cst_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
