  %max_logits_bcast = stablehlo.broadcast_in_dim %max_logits 
    {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Step 3: Subtract max_logits from logits for numerical stability
  %logits_shifted = stablehlo.subtract %arg0, %max_logits_bcast : tensor<6x7xf32>

  // Step 4: Exponentiate shifted logits
