  // Step 5: Sum exp_logits over dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = stablehlo.reduce(%exp_logits, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Step 6: Broadcast sum_exp to shape <6x7>
  %sum_exp_bcast = stablehlo.broadcast_in_dim %sum_exp 
    {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x7xf32>

  // Step 7: Compute log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp_bcast : tensor<6x7xf32>

  // Step 8: Compute log_softmax = logits_shifted - log_sum_exp
  %log_softmax = stablehlo.subtract %logits_shifted, %log_sum_exp : tensor<6x7xf32>

